int x = 10;
printf("%d", x++);

What will be the output of the following code?
int a = 5;
int b = ++a;
printf("%d", b);

What will be the output of the following code?
int x=5;
if(x=0) printf("Zero"); else printf("Non-zero");

What is the output of the following code?
int a = 10;
printf("%d", a>>1);
